import{_ as n,a0 as l,w as d,s,ao as p,I as i,x as e,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在Linux下創建一個不可變更的文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux下創建一個不可變更的文件 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux下創建一個不可變更的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux下創建一個不可變更的文件 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150123 How to make a file immutable on Linux","title":"如何在Linux下創建一個不可變更的文件","tag":"201505","desc":""},"relativePath":"201505/20150123 How to make a file immutable on Linux.md","filePath":"[post].md"}'),c={name:"201505/20150123 How to make a file immutable on Linux.md"};function u(m,t,x,f,h,L){const o=l("Link");return d(),s("div",null,[t[13]||(t[13]=p(`<h1 id="如何在linux下創建一個不可變更的文件" tabindex="-1">如何在Linux下創建一個不可變更的文件 <a class="header-anchor" href="#如何在linux下創建一個不可變更的文件" aria-label="Permalink to “如何在Linux下創建一個不可變更的文件”">​</a></h1><p>假如你想對Linux中的一些重要文件做寫保護，這樣它們就不能被刪除或者被篡改成之前的版本或者其他東西，或者在其他情況下，你可能想避免某些配置文件被軟件自動修改。使用<code>chown</code>和<code>chmod</code>命令修改文件的歸屬關係或者權限位是處理這種情況的一個解決方法，但這並不完美，因為這樣無法避免有root權限的操作。這時<code>chattr</code>就派上用場了。</p><p><code>chattr</code>是一個可以設置或取消文件的標誌位的Linux命令，它和標準的文件權限（讀、寫、執行）是分離的。與此相關的另一個命令是<code>lsattr</code>，它可以顯示文件的哪些標誌位被設置上了。最初只有EXT文件系統（EXT2/3/4）支持<code>chattr</code>和<code>lsattr</code>所管理的標誌位，但現在很多其他的原生的Linux文件系統都支持了，比如XFS、Btrfs、ReiserFS等等。</p><p>在這個教程中，我會示範如果使用<code>chattr</code>來讓Linux中的文件不可變更。</p><p><code>chattr</code>和<code>lsattr</code>命令是e2fsprogs包的一部分，它在所有現代Linux發行版都預裝了。</p><p>下面是<code>chattr</code>的基本語法。</p><pre><code>$ chattr [-RVf] [操作符][標誌位] 文件...
</code></pre><p>其中操作符可以是“+”（把選定的標誌位添加到標誌位列表）、“-”（從標誌位列表中移除選定的標誌位）、或者“=”（強制使用選定的標誌位）。</p><p>下面是一些可用的標誌位。</p><ul><li><strong>a</strong>: 只能以追加模式打開。</li><li><strong>A</strong>: 不能更新atime（文件訪問時間）。</li><li><strong>c</strong>: 當被寫入磁盤時被自動壓縮。</li><li><strong>C</strong>: 關掉“寫時複製”。</li><li><strong>i</strong>: 不可變更。</li><li><strong>s</strong>: 通過自動歸零來安全刪除。（LCTT 譯註：一般情況文件被刪後內容不會被修改，改標誌位會使得文件被刪後原有內容被“0”取代）</li></ul><h3 id="不可變更-標誌位" tabindex="-1">“不可變更”標誌位 <a class="header-anchor" href="#不可變更-標誌位" aria-label="Permalink to ““不可變更”標誌位”">​</a></h3><p>為了讓一個文件不可變更，你需要按照如下方法為這個文件添加“不可變更”標誌位。例如，對/etc/passwd文件做寫保護：</p><pre><code>$ sudo chattr +i /etc/passwd
</code></pre><p>注意設置或取消一個文件的“不可變更”標誌位是需要root用户權限的。現在檢查該文件“不可變更”標誌位是否被添加上了。</p><pre><code>$ lsattr /etc/passwd
</code></pre><p>一旦文件被設置為不可變更，任何用户都將無法修改該文件。即使是root用户也不可以修改、刪除、覆蓋、移動或者重命名這個文件。如果你想再次修改這個文件，需要先把“不可變更”標誌位取消了。</p><p>用如下命令取消“不可變更”標誌位：</p><pre><code>$ sudo chattr -i /etc/passwd
</code></pre><p><img src="https://farm9.staticflickr.com/8613/16152651317_076a65cf50_b.jpg" alt=""></p><p>如果你想讓一個目錄（比如/etc）連同它下邊的所有內容不可變更，使用“-R”選項：</p><pre><code>$ sudo chattr -R +i /etc
</code></pre><h3 id="只可追加-標誌位" tabindex="-1">“只可追加”標誌位 <a class="header-anchor" href="#只可追加-標誌位" aria-label="Permalink to ““只可追加”標誌位”">​</a></h3><p>另一個有用的的標誌位是“只可追加”，它只允許文件內容被追加的方式修改。你不能覆蓋或者刪除一個設置了“只可追加”標誌位的文件。這個標誌位在你想避免日誌文件被意外清理掉的情況很有用。</p><p>和“不可變更”標誌位類似，你可以使用如下命令讓文件變成“只可追加”模式：</p><pre><code>$ sudo chattr +a /var/log/syslog
</code></pre><p>注意當你複製一個“不可變更”或者“只可追加”的文件到其他地方後，新文件不會保留這些標誌位！</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這個教程中，我展示瞭如何使用<code>chattr</code>和<code>lsattr</code>命令來管理額外的文件標誌位，來避免文件被篡改（意外或者其他情況）的方法。注意你不能將<code>chattr</code>作為一個安全措施，因為“不可變更”標誌位可以很容易被取消掉。解決這個問題的一個可能的方式是限制<code>chattr</code>命令自身的可用性，或者去掉CAP_LINUX_IMMUTABLE內核權能標誌。關於<code>chattr</code>以及可用的標誌位的更多細節，請參考它的man手冊。</p><hr>`,29)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),a(o,{href:"http://xmodulo.com/make-file-immutable-linux.html"},{default:r(()=>[...t[0]||(t[0]=[e("http://xmodulo.com/make-file-immutable-linux.html",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=e("作者：",-1)),a(o,{href:"http://xmodulo.com/author/nanni"},{default:r(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),a(o,{href:"https://github.com/goreliu"},{default:r(()=>[...t[3]||(t[3]=[e("goreliu",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),a(o,{href:"http://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const b=n(c,[["render",u]]);export{C as __pageData,b as default};
